const $=s=>document.querySelector(s);
const photo=(id,w=800)=>`https://images.unsplash.com/${id}?auto=format&fit=crop&w=${w}&q=85`;
const photos={soup:photo('photo-1547592180-85f173990554'),rice:photo('photo-1512058564366-18510be2db19'),noodle:photo('photo-1569718212165-3a8278d5f624'),sea:photo('photo-1559737558-2f5a35f4523b'),table:photo('photo-1498654896293-37aacf113fd9')};
const foods=[{id:1,name:'돼지국밥',region:'부산',season:'겨울',tag:'뜨끈한 부산의 한 그릇',desc:'뽀얀 국물에 담긴 부산의 정과 든든함.',image:photos.soup,rating:'4.8',count:128,story:'부산을 떠올리게 하는 대표적인 한 그릇. 취향에 따라 새우젓으로 간을 맞추고 부추를 곁들여 즐겨보세요. 처음에는 국물 자체의 맛을 느껴보는 것도 좋습니다.',area:'부산진구 서면'},{id:2,name:'진주비빔밥',region:'경남',season:'봄',tag:'꽃처럼 피어난 한 상',desc:'다채로운 나물과 고소한 고명이 만나는 맛.',image:photos.rice,rating:'4.7',count:86,story:'나물과 고명을 정갈하게 올린 진주의 비빔밥. 각 재료의 색과 식감을 살펴본 뒤 고추장을 조금씩 넣어 비벼보세요.',area:'수영구 광안리'},{id:3,name:'안동찜닭',region:'경북',season:'가을',tag:'함께 나누면 더 맛있는',desc:'달큰한 간장 양념, 쫄깃한 당면 한 젓가락.',image:photos.table,rating:'4.6',count:94,story:'간장 양념에 닭고기와 채소, 당면을 함께 조린 음식. 매운맛의 정도를 확인하고 주문하면 취향에 맞게 즐길 수 있습니다.',area:'남구 대연동'},{id:4,name:'밀면',region:'부산',season:'여름',tag:'부산의 시원한 여름',desc:'시원한 육수에 쫄깃한 면발, 여름의 한 입.',image:photos.noodle,rating:'4.8',count:152,story:'밀가루로 만든 면을 시원한 육수 또는 비빔 양념과 즐기는 부산의 음식. 식초와 겨자는 맛을 본 뒤 조금씩 넣어보세요.',area:'동래구 온천동'},{id:5,name:'충무김밥',region:'경남',season:'가을',tag:'작지만 알찬 바다의 맛',desc:'담백한 꼬마김밥과 매콤한 반찬의 조화.',image:photos.rice,rating:'4.5',count:63,story:'김에 싼 작은 밥과 매콤한 반찬을 함께 먹는 음식. 김밥과 반찬을 번갈아 먹으며 담백함과 매콤함의 균형을 즐겨보세요.',area:'중구 남포동'},{id:6,name:'포항 물회',region:'경북',season:'여름',tag:'입안 가득 동해의 시원함',desc:'새콤한 양념에 싱싱한 식감을 더한 한 그릇.',image:photos.sea,rating:'4.7',count:71,story:'회와 채소를 새콤한 양념으로 즐기는 음식. 가게마다 육수와 곁들이는 방식이 다르니 추천하는 먹는 법을 물어보세요.',area:'해운대구 해운대'}];
const initialPosts=[{id:1,type:'메뉴 추천',title:'비 오는 날, 국밥 말고 생각나는 음식 있나요?',body:'따뜻한 국물이 당기는데 오늘은 새로운 메뉴를 먹어보고 싶어요. 여러분의 비 오는 날 한 끼를 추천해주세요!',author:'한입부산',location:'부산진구',likes:12},{id:2,type:'식문화 토론',title:'밀면에 식초와 겨자, 처음부터 넣으시나요?',body:'저는 육수를 먼저 먹어보고 넣는 편이에요. 여러분만의 밀면 먹는 순서가 궁금합니다.',author:'면러버',location:'동래구',likes:24},{id:3,type:'오늘의 음식',title:'오늘 점심은 든든한 국밥 한 그릇',body:'쌀쌀한 날씨에 잘 어울리는 점심이었어요. 부추를 듬뿍 넣으니 더 맛있네요.',author:'부산한상',location:'부산진구 서면',image:photos.soup,likes:18}];
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}let saved=read('gs-saved',[]),posts=read('gs-posts',initialPosts),liked=read('gs-liked',[]),page='home',region='전체',season='전체',query='',board='전체';
function persist(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch{toast('저장 공간이 부족합니다. 사진 크기를 줄여주세요.');return false}}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function cards(list){return list.length?list.map(f=>`<article class="food-card"><div class="food-img" data-food="${f.id}"><img src="${f.image}" alt="${f.name} 소개용 연출 이미지" loading="lazy"><span class="badge">${f.region}의 맛</span><button class="heart ${saved.includes(f.id)?'on':''}" data-save="${f.id}" aria-label="${f.name} 저장" aria-pressed="${saved.includes(f.id)}">${saved.includes(f.id)?'♥':'♡'}</button></div><div class="food-meta">${f.region} · ${f.season} 추천</div><h3 data-food="${f.id}">${f.name}</h3><p>${f.desc}</p><div class="food-foot"><span><b>★ ${f.rating}</b> 미식평 ${f.count}</span><button data-food="${f.id}">부산에서 만나기 ↗</button></div></article>`).join(''):'<div class="empty">조건에 맞는 음식이 없어요.<br>다른 지역이나 계절을 선택해보세요.</div>'}
function filtered(){return foods.filter(f=>(region==='전체'||f.region===region)&&(season==='전체'||f.season===season)&&(!query||`${f.name} ${f.region} ${f.desc}`.includes(query)))}
function home(){return `<section class="hero"><div><div class="eyebrow">A TASTE OF GYEONGSANG, IN BUSAN</div><h1>경상도의 맛,<br><em>부산에서</em> 만나다.</h1><p>익숙한 한 그릇에 담긴 낯선 이야기.<br>경상도 곳곳의 음식을 발견하고, 부산에서 맛보세요.</p><form class="search" id="search-form"><span>⌕</span><input aria-label="음식 검색" name="q" value="${esc(query)}" placeholder="어떤 음식이 생각나세요? 음식, 지역 검색"><button>찾기 →</button></form></div><div class="hero-photo"><img src="${photos.table}" alt="다양한 음식이 차려진 식탁"><div class="hero-stamp">LOCAL FOOD<br>경상의 맛<br>BUSAN, KOREA</div><div class="photo-label"><small>이달의 미식 이야기 · NOVEMBER</small><h3>찬 바람 불면, 따뜻한 한 상</h3><span>오래 끓여낸 정성으로 채우는 계절</span></div></div></section><div class="ticker"><span><b>제철 한 입</b> 찬 바람과 함께 돌아온, 뜨끈한 국물의 계절</span><span>우리의 맛있는 일상에 관하여 ↗</span></div><section class="section" id="explore"><div class="section-head"><div><div class="eyebrow">DISCOVER LOCAL FLAVORS</div><h2>어디의 맛이 궁금하세요?</h2><p>지역 따라, 계절 따라. 나만의 경상도 미식 여행.</p></div><span class="text-link" id="result-count">${filtered().length}가지 맛의 발견</span></div><div class="filters"><div class="chips">${['전체','부산','경남','경북'].map(r=>`<button class="chip ${region===r?'active':''}" data-region="${r}">${r==='전체'?'모든 지역':r}</button>`).join('')}</div><label><select id="season" aria-label="계절 필터">${['전체','봄','여름','가을','겨울'].map(s=>`<option ${s===season?'selected':''} value="${s}">${s==='전체'?'사계절 모두':s+'의 맛'}</option>`).join('')}</select></label></div><div class="grid" id="food-grid">${cards(filtered())}</div></section><section class="story-banner"><div class="story-copy"><div class="eyebrow">BEYOND THE TASTE</div><h2>국밥에 부추 한 줌,<br>그 한 끗의 이야기.</h2><p>소스 하나, 먹는 순서 하나에도 지역의 이야기가 있어요.<br>알고 먹으면 더 맛있는 경상도의 식문화.</p><button data-page="culture">식문화 이야기 읽기 ⟶</button></div><div class="story-image" role="img" aria-label="함께 나누는 식탁"></div></section><section class="section"><div class="section-head"><div><div class="eyebrow">OUR TABLE, OUR STORIES</div><h2>함께 나누면 더 맛있으니까.</h2><p>오늘 먹은 한 끼부터, 취향이 담긴 이야기까지.</p></div><button class="text-link" data-page="community">모두 보기 ↗</button></div><div class="community-preview"><div class="board-box">${posts.slice(0,3).map(p=>`<button class="board-row" data-post="${p.id}"><div><span class="tag">${esc(p.type)}</span><b>${esc(p.title)}</b></div><small>♡ ${p.likes}</small></button>`).join('')}</div><div class="story-copy" style="background:#ede8dc;border-radius:8px"><div class="eyebrow">TODAY'S FOOD</div><h2>당신의 오늘은<br>어떤 맛이었나요?</h2><p>한 장의 사진, 한 곳의 장소.<br>나만의 맛있는 순간을 식탁에 올려주세요.</p><button class="primary" data-write="오늘의 음식">나의 한 끼 기록하기 ＋</button></div></div></section>`}
const cultures=[{icon:'🥣',title:'국밥에 부추 한 줌,<br>새우젓은 조금씩',sub:'부산 · 양념과 곁들임',text:'국밥을 받으면 먼저 국물을 한 숟가락 맛보세요. 새우젓은 조금씩 넣어 간을 맞추고, 부추무침을 곁들여 식감을 더해보세요. 양념장은 취향에 따라 더하면 됩니다. 가게마다 기본 간이 다르니 맛을 보면서 조절하는 것이 좋아요.'},{icon:'🥢',title:'밀면 한 그릇,<br>나만의 순서로',sub:'부산 · 음식 먹는 법',text:'시원한 육수부터 한 모금. 양념장을 풀기 전과 후의 맛을 비교해보세요. 식초와 겨자는 소량씩 넣어 취향을 찾아보면 좋아요. 면을 자르는 횟수나 양념을 넣는 순서에 정답은 없습니다. 편하고 맛있게 즐겨보세요.'},{icon:'🍚',title:'반찬과 밥 사이,<br>함께 먹는 즐거움',sub:'경남 · 한 상의 문화',text:'작은 김밥과 곁들임을 함께 맛보는 충무김밥처럼, 음식의 매력은 조합에서 나오기도 합니다. 담백한 밥과 매콤한 반찬을 번갈아 먹으며 각각의 맛을 느껴보세요. 개인 접시를 이용하면 함께 나누는 식탁도 더 편안해집니다.'}];
function culturePage(){return `<section class="page-top"><div class="eyebrow">BEYOND THE TASTE</div><h1 class="page-title">알고 먹으면, 더 맛있는 이야기</h1><p class="intro">소스부터 먹는 법까지. 경상도의 식탁을 조금 더 가까이.</p></section><section class="section culture-grid">${cultures.map((c,i)=>`<button class="culture-card" data-culture="${i}"><div class="culture-icon">${c.icon}</div><p>${c.sub}</p><h3>${c.title}</h3><span>이야기 읽기 →</span></button>`).join('')}</section><p class="intro">먹는 방법은 지역과 가게, 개인의 취향에 따라 다를 수 있어요.</p>`}
function reviewsPage(){return `<section class="page-top"><div class="eyebrow">TASTE NOTES</div><h1 class="page-title">한 입에 담긴, 솔직한 미식평</h1><p class="intro">음식별 · 가게별로 살펴보는 우리의 입맛. 아래 리뷰와 식당은 시연용입니다.</p></section><div class="board-tools"><div class="chips"><button class="chip active" data-review-view="food">음식별</button><button class="chip" data-review-view="store">가게별</button></div><button class="primary" data-review-write>미식평 쓰기 ＋</button></div><div class="review-grid" id="review-grid">${reviewCards('food')}</div>`}
let customReviews=read('gs-reviews',[]);
function reviewCards(mode){return [...customReviews,...foods.slice(0,6).map((f,i)=>({food:f.name,store:f.area+' 예시식당',rating:f.rating,text:['추운 날 생각나는 든든한 맛이에요. 곁들이는 반찬과 함께 먹으니 더욱 좋았어요.','재료의 조합이 좋아서 마지막 한 입까지 즐겁게 먹었습니다.','친구와 함께 나눠 먹기 좋은 메뉴예요. 다음에도 생각날 것 같아요.'][i%3],author:['부산한상','맛있는산책','한입기록'][i%3]}))].map(r=>`<article class="review"><span class="tag">${esc(mode==='store'?r.food:r.store)}</span><h3>${esc(mode==='store'?r.store:r.food)}</h3><div class="stars">★ ${esc(r.rating)} <small> / 5</small></div><p>${esc(r.text)}</p><small>${esc(r.author)} · ${customReviews.includes(r)?'내가 작성한 리뷰':'체험용 미식평'}</small></article>`).join('')}
function communityPage(){const list=posts.filter(p=>board==='전체'||p.type===board);return `<section class="page-top"><div class="eyebrow">OUR TABLE</div><h1 class="page-title">우리들의 식탁</h1><p class="intro">오늘의 메뉴를 묻고, 다른 취향을 만나고, 맛있는 순간을 나눠요.</p></section><div class="board-tools"><div class="chips">${['전체','메뉴 추천','식문화 토론','오늘의 음식'].map(t=>`<button class="chip ${t===board?'active':''}" data-board="${t}">${t}</button>`).join('')}</div><button class="primary" data-write="${board==='전체'?'메뉴 추천':board}">글쓰기 ＋</button></div><div class="post-list">${list.length?list.map(p=>`<article class="post" data-post="${p.id}" tabindex="0" role="button"><span class="tag">${esc(p.type)}</span><h3>${esc(p.title)}</h3><p>${esc(p.body)}</p>${p.image?`<img class="post-photo" src="${p.image}" alt="${esc(p.title)}" loading="lazy">`:''}<small>${esc(p.author)} · ${esc(p.location||'부산')} <span style="float:right">♡ ${p.likes}</span></small></article>`).join(''):'<div class="empty">첫 번째 이야기를 남겨주세요.</div>'}</div>`}
function render(){document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#app').innerHTML=page==='home'?home():page==='culture'?culturePage():page==='reviews'?reviewsPage():page==='community'?communityPage():`<section class="page-top"><div class="eyebrow">MY TASTE COLLECTION</div><h1 class="page-title">다음에 만나고 싶은 맛</h1><p class="intro">마음에 담아둔 경상도의 음식들.</p></section><div class="section grid">${saved.length?cards(foods.filter(f=>saved.includes(f.id))):'<div class="empty">아직 저장한 음식이 없어요.<br>음식 사진의 ♡를 눌러 나만의 목록을 만들어보세요.<br><br><button class="primary" data-page="home">맛 탐색하러 가기 →</button></div>'}</div>`}
function navigate(p){page=p;location.hash=p;render();window.scrollTo({top:0,behavior:'smooth'})}
function modal(html){$('#modal-body').innerHTML=html;$('#modal').showModal()}
function foodDetail(id){const f=foods.find(f=>f.id===id);modal(`<img class="cover" src="${f.image}" alt="${f.name} 소개용 연출 이미지"><p class="eyebrow">${f.region} · ${f.season}의 맛</p><h2>${f.name}</h2><p>${f.story}</p><button class="primary" data-save="${id}">${saved.includes(id)?'♥ 저장됨':'♡ 이 음식 저장하기'}</button><h3>부산에서 이 맛을 만나보세요</h3><div class="restaurant"><b>${f.area} 예시식당</b><p>${f.name} 전문 · ★ ${f.rating} (예시)</p><small>실제 영업 중인 가게 정보가 아닌 화면 시연용 정보입니다.</small><br><a href="https://map.naver.com/p/search/${encodeURIComponent('부산 '+f.name)}" target="_blank" rel="noopener noreferrer">네이버 지도에서 실제 식당 검색 ↗</a></div><p class="form-note">사진은 음식 소개를 위한 연출 이미지입니다.</p>`)}
function writePost(type){modal(`<div class="eyebrow">A NEW STORY ON OUR TABLE</div><h2>맛있는 이야기 남기기</h2><form id="post-form"><label for="post-type">게시판</label><select id="post-type" name="type">${['메뉴 추천','식문화 토론','오늘의 음식'].map(t=>`<option ${t===type?'selected':''}>${t}</option>`).join('')}</select><label for="post-title">제목</label><input id="post-title" name="title" maxlength="70" placeholder="오늘은 어떤 이야기를 나눠볼까요?" required><label for="post-body">내용</label><textarea id="post-body" name="body" maxlength="2000" placeholder="음식에 담긴 나만의 이야기를 적어주세요." required></textarea><label for="post-location">장소</label><input id="post-location" name="location" maxlength="80" placeholder="예: 부산 수영구 광안리"><label for="post-author">닉네임</label><input id="post-author" name="author" maxlength="20" placeholder="예: 한입부산" required><label for="post-image">음식 사진 (선택)</label><input id="post-image" type="file" accept="image/*"><p class="form-note">사진은 3MB 이하로 선택해주세요. 글은 현재 브라우저에만 저장됩니다.</p><button class="primary" type="submit">식탁에 이야기 올리기 →</button></form>`)}
document.addEventListener('click',e=>{const save=e.target.closest('[data-save]');if(save){const id=+save.dataset.save;const next=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];if(persist('gs-saved',next)){saved=next;toast(saved.includes(id)?'나만의 맛 목록에 저장했어요.':'저장을 해제했어요.');render();if($('#modal').open)foodDetailUpdate(id)}return}const nav=e.target.closest('[data-page]');if(nav){navigate(nav.dataset.page);return}const f=e.target.closest('[data-food]');if(f){foodDetail(+f.dataset.food);return}const reg=e.target.closest('[data-region]');if(reg){region=reg.dataset.region;render();return}const c=e.target.closest('[data-culture]');if(c){const story=cultures[+c.dataset.culture];modal(`<div class="culture-icon">${story.icon}</div><p class="eyebrow">${story.sub}</p><h2>${story.title}</h2><p>${story.text}</p><button class="primary" data-discuss>이 이야기, 함께 나눠보기 →</button>`);return}if(e.target.closest('[data-discuss]')){$('#modal').close();board='식문화 토론';navigate('community');return}const b=e.target.closest('[data-board]');if(b){board=b.dataset.board;render();return}const w=e.target.closest('[data-write]');if(w){writePost(w.dataset.write);return}const post=e.target.closest('[data-post]');if(post){const p=posts.find(p=>p.id===+post.dataset.post);modal(`<span class="tag">${esc(p.type)}</span><h2>${esc(p.title)}</h2><small>${esc(p.author)} · ${esc(p.location||'부산')}</small>${p.image?`<img class="post-photo" src="${p.image}" alt="음식 사진">`:''}<p style="white-space:pre-wrap">${esc(p.body)}</p><button class="primary" data-like="${p.id}">${liked.includes(p.id)?'♥':'♡'} 공감 ${p.likes}</button><p class="form-note">${initialPosts.some(x=>x.id===p.id)?'시험본의 예시 게시글입니다.':'이 브라우저에서 작성한 게시글입니다.'}</p>`);return}const l=e.target.closest('[data-like]');if(l){const id=+l.dataset.like,p=posts.find(p=>p.id===id);p.likes+=liked.includes(id)?-1:1;liked=liked.includes(id)?liked.filter(x=>x!==id):[...liked,id];persist('gs-posts',posts);persist('gs-liked',liked);l.textContent=`${liked.includes(id)?'♥':'♡'} 공감 ${p.likes}`;render();return}const rv=e.target.closest('[data-review-view]');if(rv){document.querySelectorAll('[data-review-view]').forEach(x=>x.classList.toggle('active',x===rv));$('#review-grid').innerHTML=reviewCards(rv.dataset.reviewView);return}if(e.target.closest('[data-review-write]'))modal(`<div class="eyebrow">MY TASTE NOTE</div><h2>미식평 남기기</h2><form id="review-form"><label>음식<select name="food">${foods.map(f=>`<option>${f.name}</option>`).join('')}</select></label><label>가게 이름<input name="store" required maxlength="60" placeholder="방문한 가게 이름"></label><label>별점<select name="rating"><option value="5">★★★★★ · 5점</option><option value="4">★★★★☆ · 4점</option><option value="3">★★★☆☆ · 3점</option><option value="2">★★☆☆☆ · 2점</option><option value="1">★☆☆☆☆ · 1점</option></select></label><label>미식평<textarea name="text" required maxlength="1000" placeholder="맛, 식감, 곁들임은 어땠나요?"></textarea></label><label>닉네임<input name="author" required maxlength="20"></label><p class="form-note">미식평은 이 브라우저에 저장됩니다.</p><button class="primary">미식평 등록하기</button></form>`)});
function foodDetailUpdate(id){const b=$('#modal [data-save]');if(b&&+b.dataset.save===id)b.textContent=saved.includes(id)?'♥ 저장됨':'♡ 이 음식 저장하기'}
document.addEventListener('change',e=>{if(e.target.id==='season'){season=e.target.value;render()}});
document.addEventListener('submit',async e=>{if(e.target.id==='search-form'){e.preventDefault();query=new FormData(e.target).get('q').trim();render();$('#explore').scrollIntoView({behavior:'smooth'});return}if(e.target.id==='review-form'){e.preventDefault();const r=Object.fromEntries(new FormData(e.target));if(persist('gs-reviews',[r,...customReviews])){customReviews.unshift(r);$('#modal').close();navigate('reviews');toast('미식평이 등록되었어요.')}return}if(e.target.id==='post-form'){e.preventDefault();const form=e.target,data=Object.fromEntries(new FormData(form)),file=$('#post-image').files[0];let image='';if(file){if(!file.type.startsWith('image/'))return toast('이미지 파일을 선택해주세요.');if(file.size>3*1024*1024)return toast('사진은 3MB 이하로 선택해주세요.');try{image=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}catch{return toast('사진을 읽을 수 없어요. 다른 파일을 선택해주세요.')}}if(!data.title.trim()||!data.body.trim()||!data.author.trim())return toast('제목, 내용, 닉네임을 입력해주세요.');const p={...data,id:Date.now(),image,likes:0};if(persist('gs-posts',[p,...posts])){posts.unshift(p);board=data.type;$('#modal').close();navigate('community');toast('새로운 이야기가 식탁에 올라왔어요.')}}});
$('#modal .close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('.post'))e.target.click()});
function fromHash(){const h=location.hash.slice(1);page=['home','reviews','culture','community','saved'].includes(h)?h:'home';render()}window.addEventListener('hashchange',fromHash);fromHash();
